const examples=[['Cylinder','x² + y² = 4',{...clone(defaults.implicit),expr:['x^2+y^2=4']}],['Implicit sphere','x² + y² + z² = 9',clone(defaults.implicit)],['Torus','r(u,v)',clone(defaults.parametric)],['Sphere','Spherical coordinates',{...clone(defaults.parametric),expr:['2*sin(v)*cos(u)','2*sin(v)*sin(u)','2*cos(v)'],ranges:['0','2*pi','0','pi']}],['Helix','Space curve r(t)',clone(defaults.curve)],['Saddle','Tangent plane',{...clone(defaults.explicit),expr:['(x^2-y^2)/5'],tangent:true}],['Vortex','Vector field',clone(defaults.field)],['Intersection','Cylinder ∩ plane',{...clone(defaults.curve),expr:['2cos(t)','2sin(t)','6-2sin(t)'],ranges:['0','2pi']}],['Möbius strip','Parametric surface',{...clone(defaults.parametric),expr:['(2+v*cos(u/2))*cos(u)','(2+v*cos(u/2))*sin(u)','v*sin(u/2)'],ranges:['0','2*pi','-0.7','0.7']}]];examples.forEach(([name,desc,obj])=>{let b=document.createElement('button');b.className='preset';b.innerHTML=`<span><b>${name}</b><small>${desc}</small></span>`;b.onclick=()=>{checkpoint();objects=[clone(obj)];document.querySelectorAll('.preset').forEach(e=>e.classList.remove('active'));b.classList.add('active');$('#newType').value=obj.type;editors();fitScene()};$('#presets').append(b)});editors();

function fitScene(){let points=[];objects.forEach((o,k)=>{let c=compiled[k];if(!c||!o.visible)return;let{f,r}=c;if(o.type==='implicit'){for(const triangle of getImplicitMesh(o,f[0]))points.push(...triangle.points);return}for(let i=0;i<=24;i++){if(o.type==='curve'){let t=r[0]+(r[1]-r[0])*i/24;points.push(f.map(fn=>fn(t)))}else for(let j=0;j<=24;j++){let u=i/24,v=j/24;if(o.type==='explicit'){let x=lo+u*(hi-lo),y=lo+v*(hi-lo);points.push([x,y,f[0](x,y)])}if(o.type==='parametric')points.push(f.map(fn=>fn(r[0]+u*(r[1]-r[0]),r[2]+v*(r[3]-r[2]))));if(o.type==='field')points.push([lo+u*(hi-lo),lo+v*(hi-lo),i%2?hi:lo])}}});points=points.filter(valid);if(!points.length)return;let mins=[Infinity,Infinity,Infinity],maxs=[-Infinity,-Infinity,-Infinity];for(const p of points)for(let k=0;k<3;k++){mins[k]=Math.min(mins[k],p[k]);maxs[k]=Math.max(maxs[k],p[k])};cameraTarget=mins.map((v,k)=>(v+maxs[k])/2);cameraSpan=Math.max(1,...maxs.map((v,k)=>v-mins[k]))*1.2;zoom=1;draw()}
$('#fit').onclick=fitScene;$('#undo').onclick=()=>{if(!history.length)return;future.push(JSON.stringify(objects));objects=JSON.parse(history.pop());editors();updateHistory()};$('#redo').onclick=()=>{if(!future.length)return;history.push(JSON.stringify(objects));objects=JSON.parse(future.pop());editors();updateHistory()};
let focusedInput=null;document.addEventListener('focusin',e=>{if(e.target.matches('.eq-input input,.parameter-bounds input'))focusedInput=e.target});document.querySelectorAll('[data-insert]').forEach(b=>b.onclick=()=>{if(!focusedInput)return;let input=focusedInput,start=input.selectionStart??input.value.length,end=input.selectionEnd??start,text=b.dataset.insert;input.value=input.value.slice(0,start)+text+input.value.slice(end);input.focus();input.setSelectionRange(start+text.length,end+text.length);input.dispatchEvent(new Event('input',{bubbles:true}))});$('#examples-toggle').onclick=()=>{let hidden=$('#presets').hidden=!$('#presets').hidden;$('#examples-toggle').textContent=hidden?'Show examples':'Hide examples';$('#examples-toggle').setAttribute('aria-expanded',!hidden)};$('#save-scene').onclick=()=>{try{let content=SceneFormat.encode({version:1,objects,a,lo,hi,view:{target:cameraTarget,span:cameraSpan,yaw,pitch,zoom,mesh,grid}}),blob=new Blob([content],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='orbit-scene.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#status').textContent='Downloaded orbit-scene.json'}catch(error){$('#status').textContent=error.message}};function restoreScene(text,label){let scene=SceneFormat.decode(text);playing=false;$('#animate').textContent='Play animation';checkpoint();objects=scene.objects;lo=scene.lo;hi=scene.hi;a=scene.a;$('#min').value=lo;$('#max').value=hi;$('#parameter').value=a;$('#aval').textContent=a.toFixed(2);editors();if(scene.view){let v=scene.view;cameraTarget=v.target;cameraSpan=v.span;yaw=v.yaw;pitch=v.pitch;zoom=v.zoom;mesh=v.mesh;grid=v.grid;$('#mesh').checked=mesh;$('#grid').checked=grid;setView('');draw()}else fitScene();$('#status').textContent='Opened '+label}
$('#open-scene').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Scene file is too large (maximum 100 KB).');restoreScene(await file.text(),file.name)}catch(error){$('#status').textContent=error.message}e.target.value=''};updateHistory();fitScene();

document.querySelector('.file-button').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#open-scene').click()}};

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialog').open)$('#dialog').close()});

function setView(id){for(const name of ['perspective','top','front','side'])$('#'+name).classList.toggle('active',name===id)}
$('#front').onclick=()=>{pitch=0;yaw=0;setView('front');draw()};$('#side').onclick=()=>{pitch=0;yaw=-Math.PI/2;setView('side');draw()};

$('#restore-text').onclick=()=>{try{restoreScene($('#scene-text').value,'pasted scene');$('#scene-text').value='';$('#paste-scene').open=false}catch(e){$('#paste-error').textContent=e.message}};
